import{_ as t,o as a,c as o,a3 as i}from"./chunks/framework.BlfGB29P.js";const h=JSON.parse('{"title":"Dépannage","description":"","frontmatter":{},"headers":[],"relativePath":"fr/projects/fritzbox-to-mqtt/troubleshooting.md","filePath":"fr/projects/fritzbox-to-mqtt/troubleshooting.md","lastUpdated":1793123188000}'),n={name:"fr/projects/fritzbox-to-mqtt/troubleshooting.md"};function r(s,e,l,d,u,c){return a(),o("div",null,[...e[0]||(e[0]=[i('<p><a id="depannage"></a><a id="statut"></a></p><h1 id="fehlersuche" tabindex="-1">Dépannage <a class="header-anchor" href="#fehlersuche" aria-label="Permalink to &quot;Dépannage {#fehlersuche}&quot;">​</a></h1><h2 id="mqtt-meldet-not-authorized" tabindex="-1">MQTT signale <code>Not authorized</code> <a class="header-anchor" href="#mqtt-meldet-not-authorized" aria-label="Permalink to &quot;MQTT signale `Not authorized` {#mqtt-meldet-not-authorized}&quot;">​</a></h2><p>L&#39;application utilise le service MQTT interne de Home Assistant. Vérifiez :</p><ul><li>que l&#39;application « Mosquitto broker » est installée et démarrée</li><li>que l&#39;intégration MQTT est configurée</li><li>que l&#39;application a été redémarrée une fois Mosquitto disponible</li></ul><h2 id="fritz-box-meldet-401-unauthorized" tabindex="-1">La FRITZ!Box signale <code>401 Unauthorized</code> <a class="header-anchor" href="#fritz-box-meldet-401-unauthorized" aria-label="Permalink to &quot;La FRITZ!Box signale `401 Unauthorized` {#fritz-box-meldet-401-unauthorized}&quot;">​</a></h2><p>Vérifiez le nom d&#39;utilisateur, le mot de passe et les autorisations de l&#39;utilisateur FRITZ!Box. L&#39;utilisateur doit disposer des droits d&#39;accès aux données FRITZ!Box requises.</p><h2 id="einzelne-werte-bleiben-unknown" tabindex="-1">Certaines valeurs restent à <code>unknown</code> <a class="header-anchor" href="#einzelne-werte-bleiben-unknown" aria-label="Permalink to &quot;Certaines valeurs restent à `unknown` {#einzelne-werte-bleiben-unknown}&quot;">​</a></h2><p>Toutes les FRITZ!Box ne fournissent pas l&#39;ensemble des données via les mêmes interfaces. L&#39;application tente d&#39;utiliser TR-064, la découverte de services (Service Discovery) ainsi que des mécanismes de repli (fallbacks) via Web/Lua. Si une valeur est manquante, activez <code>log_value_details</code> et examinez les lignes de journal correspondantes.</p><h2 id="port-1012" tabindex="-1">Port <code>1012</code> <a class="header-anchor" href="#port-1012" aria-label="Permalink to &quot;Port `1012` {#port-1012}&quot;">​</a></h2><p>Le port <code>1012</code> est réservé au suivi des appels en temps réel. Les débits d&#39;envoi (upload) et de réception (download) ainsi que l&#39;état de la FRITZ!Box ne sont pas transmis via le port <code>1012</code>.</p><h2 id="hacs-findet-das-projekt-nicht" tabindex="-1">HACS ne trouve pas le projet <a class="header-anchor" href="#hacs-findet-das-projekt-nicht" aria-label="Permalink to &quot;HACS ne trouve pas le projet {#hacs-findet-das-projekt-nicht}&quot;">​</a></h2><p>C&#39;est normal. Ce projet est une application « Supervisor » ; il s&#39;installe en tant que dépôt (repository) via la boutique d&#39;applications de Home Assistant, et non via HACS.</p>',13)])])}const m=t(n,[["render",r]]);export{h as __pageData,m as default};
